import { useMemo, useLayoutEffect, useState, useEffect } from 'react';
import { RouterProvider } from 'react-router';
import { shellui } from '@shellui/sdk';
import { useConfig } from './features/config/useConfig';
import { ConfigProvider } from './features/config/ConfigProvider';
import { createAppRouter } from './routes/router';
import { SettingsProvider } from './features/settings/SettingsProvider';
import { ThemeProvider } from './features/theme/ThemeProvider';
import { I18nProvider } from './i18n/I18nProvider';
import { DialogProvider } from './features/alertDialog/DialogContext';
import { CookieConsentModal } from './features/cookieConsent/CookieConsentModal';
import { AuthProvider } from './features/auth/AuthProvider';
import { StorageBridge } from './features/storage/StorageBridge';
import { SonnerProvider } from './features/sonner/SonnerContext';
import { Toaster } from './components/ui/sonner';
import { UploadToaster } from './features/storage/uploads/UploadToaster';
import './features/sentry/initSentry';
import './i18n/config'; // Initialize i18n
import './index.css';
import {
  registerServiceWorker,
  unregisterServiceWorker,
  isTauri,
  isServiceWorkerEnabledInSettings,
  ensureServiceWorkerDisabledWhenOff,
} from './service-worker/register';
import { useSettings } from './features/settings/hooks/useSettings';
import { DesktopChrome } from './features/layouts/chrome/DesktopChrome';

const AppContent = () => {
  const { config } = useConfig();
  const { settings } = useSettings();

  // Apply favicon from config when available (allows projects to override default)
  useEffect(() => {
    if (config?.favicon) {
      const link = document.querySelector<HTMLLinkElement>('link[rel="icon"]');
      if (link) link.href = config.favicon;
    }
  }, [config?.favicon]);

  // Unregister any stale service worker as early as possible when the setting is off
  useLayoutEffect(() => {
    if (isTauri()) {
      void unregisterServiceWorker();
      return;
    }
    if (!isServiceWorkerEnabledInSettings()) {
      void ensureServiceWorkerDisabledWhenOff();
    }
  }, []);

  // Register or unregister service worker based on setting
  useEffect(() => {
    if (isTauri()) {
      unregisterServiceWorker();
      return;
    }
    const serviceWorkerEnabled = settings?.serviceWorker?.enabled ?? false;

    // Don't register service worker if navigation is empty or undefined
    // This helps prevent issues in development or misconfigured apps
    if (!config?.navigation || config.navigation.length === 0) {
      if (serviceWorkerEnabled) {
        // eslint-disable-next-line no-console
        console.warn('[Service Worker] Disabled: No navigation items configured');
        unregisterServiceWorker();
      }
      return;
    }

    if (serviceWorkerEnabled) {
      registerServiceWorker({
        enabled: true,
      });
    } else {
      unregisterServiceWorker();
      void ensureServiceWorkerDisabledWhenOff();
    }
  }, [settings?.serviceWorker?.enabled, config?.navigation]);

  // Create router from config using data mode
  const router = useMemo(() => {
    if (!config) {
      return null;
    }
    return createAppRouter(config);
  }, [config]);

  // If no navigation, show simple layout
  if (!config.navigation || config.navigation.length === 0) {
    return (
      <>
        <DesktopChrome />
        <CookieConsentModal />
        <div style={{ fontFamily: 'system-ui, sans-serif', padding: '2rem' }}>
          <h1>{config.title || 'Shellui'}</h1>
          <p>No navigation items configured.</p>
        </div>
      </>
    );
  }

  if (!router) {
    return null;
  }

  return (
    <>
      <DesktopChrome />
      <CookieConsentModal />
      <RouterProvider router={router} />
    </>
  );
};

const App = () => {
  const [isLoading, setIsLoading] = useState(true);
  // Initialize Shellui SDK to support recursive nesting
  useLayoutEffect(() => {
    shellui.init().then(() => {
      setIsLoading(false);
    });
  }, []);

  if (isLoading) {
    return null;
  }

  return (
    <ConfigProvider>
      <AuthProvider>
        <StorageBridge />
        <SettingsProvider>
          <ThemeProvider>
            <I18nProvider>
              <DialogProvider>
                <SonnerProvider>
                  {/* Toaster + upload progress live at Shellui root so they survive navigation. */}
                  <Toaster />
                  <UploadToaster />
                  <AppContent />
                </SonnerProvider>
              </DialogProvider>
            </I18nProvider>
          </ThemeProvider>
        </SettingsProvider>
      </AuthProvider>
    </ConfigProvider>
  );
};

export default App;
