import { createBrowserRouter } from 'react-router';
import type { ShellUIConfig } from '../features/config/types';
import { createRoutes } from './routes';

function readHostingBasename(): string | undefined {
  if (typeof window === 'undefined') return undefined;
  const value = (window as unknown as { __SHELLUI_BASENAME__?: unknown }).__SHELLUI_BASENAME__;
  return typeof value === 'string' && value.trim() ? value.trim() : undefined;
}

export const createAppRouter = (config: ShellUIConfig) => {
  const routes = createRoutes(config);
  const basename = readHostingBasename();
  return createBrowserRouter(routes, basename ? { basename } : undefined);
};
